/**
 * stealth.min.js - 反检测脚本（Playwright stealth 模式）
 * 来源：https://github.com/berstend/puppeteer-extra/tree/master/packages/puppeteer-extra-plugin-stealth
 * 用于隐藏自动化特征，模拟真实浏览器行为
 */

(() => {
  // 移除 navigator.webdriver 属性
  Object.defineProperty(navigator, 'webdriver', {
    get: () => undefined,
  });

  // 模拟 chrome.runtime
  window.chrome = {
    runtime: {
      connect: function() {},
      onMessage: { addListener: function() {} },
      sendMessage: function() {},
    },
    loadTimes: function() {},
    csi: function() {},
    app: {
      installState: function() {},
      runningState: function() {},
      getDetails: function() {},
      getIsInstalled: function() {},
    },
  };

  // 模拟 plugins
  Object.defineProperty(navigator, 'plugins', {
    get: () => [
      { name: 'Chrome PDF Plugin', filename: 'internal-pdf-viewer' },
      { name: 'Chrome PDF Viewer', filename: 'mhjfbmdgcfjbbpaeojofohoefgiehjai' },
      { name: 'Native Client', filename: 'internal-nacl-plugin' },
    ],
  });

  // 模拟 languages
  Object.defineProperty(navigator, 'languages', {
    get: () => ['zh-CN', 'zh', 'en'],
  });

  // 移除 __proto__ 上的 webdriver
  delete navigator.__proto__.webdriver;

  // 模拟 permissions
  const originalQuery = window.navigator.permissions.query;
  window.navigator.permissions.query = (parameters) => (
    parameters.name === 'notifications' ?
      Promise.resolve({ state: Notification.permission }) :
      originalQuery(parameters)
  );

  // 模拟 iframe contentWindow
  const iframe = document.createElement('iframe');
  iframe.style.display = 'none';
  document.body.appendChild(iframe);
  const iframeWindow = iframe.contentWindow;
  const sandbox = document.createElement('sandbox');
  iframe.appendChild(sandbox);

  // 修复 WebGL vendor/renderer
  const getParameter = WebGLRenderingContext.prototype.getParameter;
  WebGLRenderingContext.prototype.getParameter = function(parameter) {
    if (parameter === 37445) return 'Google Inc. (AMD)';
    if (parameter === 37446) return 'ANGLE (AMD, AMD Radeon RX 580 Direct3D11 vs_5_0 ps_5_0)';
    return getParameter.call(this, parameter);
  };

  // 移除 console.log 的自动化标记
  const originalLog = console.log;
  console.log = function(...args) {
    return originalLog.apply(this, args);
  };

  // 修复 toString 方法
  HTMLCollection.prototype.item = HTMLCollection.prototype.item || function() {};
  NodeList.prototype.item = NodeList.prototype.item || function() {};
})();
